/** A row the backlog only names: nothing documented, a class and numbers entirely [PROPOSÉ]. */
const nameOnly = (row, classFr, classEn) => ({
  refs: [], evidence: NAME, verified: false, documented: [],
  fr: `Arme inscrite au suivi (${row.work}) sous le nom « ${row.name} » ; aucune fiche n’a pu être relue. Jouable comme ${classFr} : classe et valeurs entièrement proposées. Plaque provisoire dessinée.`,
  en: `Weapon recorded in the backlog (${row.work}) as “${row.name}”; no page could be re-read. Playable as ${classEn}: class and values are entirely proposed. Provisional drawn plaque.`,
  ...row,
  toDefine: ['identité, classe et mécanisme (aucune source relue)', ...(row.toDefine || []), 'plaque native']
});

